scwin.test = function(rowIndex, colIndex, label) {
    if (label.indexOf("googlelogo_color_272x92dp") > -1) {
        label = "맑음";
    }
    return label;
};
scwin.mouseOverBehaviour = function(id) {
    var myElement = WebSquare.wUnit.getDomById($p.id + id);
    myElement.addEventListener("mouseover", function() {
        console.log('hover');
    });
    var mouseEvent = document.createEvent("MouseEvent");
    mouseEvent.initEvent('mouseover', true, true);
    myElement.dispatchEvent(mouseEvent);
}
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getObjById('gridView1_tooltip');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 0. 샘플파일의 default는 showImageTooltip = 'false'
    //0. The default in the sample file is showImageTooltip = 'false'
    // verify step 0
    // Test step 1. 샘플파일을 실행 후 name4항목의 이미지에 마우스를 오버한다.
    //1. Execute the sample file and mouse over the image of name4 item.
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'gridView1_cell_0_3')");
    //Verify step 1. tooltip이 보여지지 않는다.(정상)
    //1. Tooltip is not shown (normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "string");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. showImageTooltip = 'true'로 설정 후(샘플 변경) name4항목의 이미지에 마우스를 오버한다.
    //2. Set showImageTooltip = 'true' (sample change) and mouse over image of name4 item.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1').setAttribute('showImageTooltip', 'true')");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'gridView1_cell_2_3')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. tooltip이 보여진다.(정상)
    //2. The tooltip is shown (normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
